    private static Chest[] Boxes()=>Managers.Inst.world.gameLayer.GetComponentsInChildren<Chest>(true);
    private static Chest Restore(int index,float localY=0)
    {
        var go=UnityEngine.Object.Instantiate(Resources.Prefab,Managers.Inst.world.gameLayer,false);
        go.name="KEM.MountIslandGems.v1/"+A+"/11/1/"+index;go.GetComponent<Chest>().currencyAmount=7;
        go.transform.localPosition=new Vector3(10+index*10,localY,1.5f);
        CampaignSaveData.current.GetIsland(11).objects.Add(new IslandSaveData.ObjectData{uniqueID="saved-"+index,name=go.name,prefabPath="Prefabs/Objects/GemChestFixedAmount",localPosition=go.transform.localPosition});
        return go.GetComponent<Chest>();
    }
    private static void Save(bool marker=true,bool normal=true,bool dropRow=false)
    {
        var c=MountIslandGemRewards.BeginIslandSave(0,11,0);var island=CampaignSaveData.current.GetIsland(11);IslandSaveData.CurrentlySavingIsland=island;island.NativeCapture();island.land=11;if(dropRow && island.objects.Count>0)island.objects.RemoveAt(0);if(marker)MountIslandGemRewards.ObserveMarker(island,true);IslandSaveData.idsByObject.Clear();IslandSaveData.objectsByID.Clear();IslandSaveData.CurrentlySavingIsland=null;MountIslandGemRewards.EndIslandSave(c,normal);
    }
